from pathlib import Path

path = Path("ClockTimer.js")
text = path.read_text()

old_decl = '''        #spinAnimation;\n\n        #spinFrozenTimeFontSize;'''
new_decl = '''        #spinAnimation;\n\n        #spinScaleAnimation;\n\n        #spinFrozenTimeFontSize;'''
if old_decl not in text:
    raise SystemExit("spin declaration block not found")
text = text.replace(old_decl, new_decl, 1)

old = '''            this.#spinAnimation\n                ?.cancel();\n\n            const scaleDuration =\n                125;\n\n            const finishSpin =\n                animation => {\n                    if (\n                        this.#spinAnimation !==\n                            animation\n                    ) {\n                        return;\n                    }\n\n                    this.#spinAnimation =\n                        undefined;\n\n                    this.#restoreTimeFontAfterSpin();\n\n                    this.#scheduleFontSizing();\n                };\n\n            const shrinkAnimation =\n                this.animate(\n                    [\n                        {\n                            transform: \"scale(1)\"\n                        },\n                        {\n                            transform: \"scale(0.95)\"\n                        }\n                    ],\n                    {\n                        duration: scaleDuration,\n                        easing: \"ease-out\",\n                        fill: \"forwards\"\n                    }\n                );\n\n            this.#spinAnimation =\n                shrinkAnimation;\n\n            shrinkAnimation.finished\n                .then(() => {\n                    if (\n                        this.#spinAnimation !==\n                            shrinkAnimation\n                    ) {\n                        return;\n                    }\n\n                    const spinAnimation =\n                        this.animate(\n                            [\n                                {\n                                    offset: 0,\n                                    transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(0deg) scale(0.95)\"\n                                },\n                                {\n                                    offset: 0.5,\n                                    transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(90deg) scale(0.95)\"\n                                },\n                                {\n                                    offset: 0.5,\n                                    transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(-90deg) scale(0.95)\"\n                                },\n                                {\n                                    offset: 1,\n                                    transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(0deg) scale(0.95)\"\n                                }\n                            ],\n                            {\n                                duration:\n                                    perRotationDuration,\n                                iterations:\n                                    rotations,\n                                easing: \"ease-in-out\",\n                                fill: \"forwards\"\n                            }\n                        );\n\n                    this.#spinAnimation =\n                        spinAnimation;\n\n                    return spinAnimation.finished\n                        .then(() => {\n                            if (\n                                this.#spinAnimation !==\n                                    spinAnimation\n                            ) {\n                                return;\n                            }\n\n                            const restoreAnimation =\n                                this.animate(\n                                    [\n                                        {\n                                            transform: \"scale(0.95)\"\n                                        },\n                                        {\n                                            transform: \"scale(1)\"\n                                        }\n                                    ],\n                                    {\n                                        duration: scaleDuration,\n                                        easing: \"ease-in\",\n                                        fill: \"forwards\"\n                                    }\n                                );\n\n                            this.#spinAnimation =\n                                restoreAnimation;\n\n                            return restoreAnimation.finished\n                                .then(() => {\n                                    finishSpin(\n                                        restoreAnimation\n                                    );\n                                });\n                        });\n                })\n                .catch(() => {});\n'''

new = '''            this.#spinAnimation\n                ?.cancel();\n\n            this.#spinScaleAnimation\n                ?.cancel();\n\n            const totalDuration =\n                perRotationDuration *\n                rotations;\n\n            const scaleDuration =\n                Math.min(\n                    125,\n                    totalDuration / 2\n                );\n\n            const scaleOffset =\n                totalDuration > 0\n                    ? scaleDuration /\n                        totalDuration\n                    : 0.5;\n\n            const spinAnimation =\n                this.animate(\n                    [\n                        {\n                            offset: 0,\n                            transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(0deg)\"\n                        },\n                        {\n                            offset: 0.5,\n                            transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(90deg)\"\n                        },\n                        {\n                            offset: 0.5,\n                            transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(-90deg)\"\n                        },\n                        {\n                            offset: 1,\n                            transform: \"perspective(var(--clock-timer-spin-perspective, 800px)) rotateY(0deg)\"\n                        }\n                    ],\n                    {\n                        duration:\n                            perRotationDuration,\n                        iterations:\n                            rotations,\n                        easing: \"ease-in-out\"\n                    }\n                );\n\n            const scaleAnimation =\n                this.animate(\n                    [\n                        {\n                            offset: 0,\n                            scale: \"1\",\n                            easing: \"ease-out\"\n                        },\n                        {\n                            offset:\n                                scaleOffset,\n                            scale: \"0.95\"\n                        },\n                        {\n                            offset:\n                                1 - scaleOffset,\n                            scale: \"0.95\",\n                            easing: \"ease-in\"\n                        },\n                        {\n                            offset: 1,\n                            scale: \"1\"\n                        }\n                    ],\n                    {\n                        duration:\n                            totalDuration,\n                        fill: \"forwards\"\n                    }\n                );\n\n            this.#spinAnimation =\n                spinAnimation;\n\n            this.#spinScaleAnimation =\n                scaleAnimation;\n\n            Promise.allSettled([\n                spinAnimation.finished,\n                scaleAnimation.finished\n            ]).then(() => {\n                if (\n                    this.#spinAnimation !==\n                        spinAnimation ||\n                    this.#spinScaleAnimation !==\n                        scaleAnimation\n                ) {\n                    return;\n                }\n\n                this.#spinAnimation =\n                    undefined;\n\n                this.#spinScaleAnimation =\n                    undefined;\n\n                scaleAnimation.cancel();\n\n                this.#restoreTimeFontAfterSpin();\n\n                this.#scheduleFontSizing();\n            });\n'''

if old not in text:
    raise SystemExit("old spin block not found")
text = text.replace(old, new, 1)
path.write_text(text)
